#!/usr/bin/env bash
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh" || { echo "directive.sh: cannot source role-directive.sh" >&2; exit 2; }
core_role_directive "YOU DECIDE: 프로덕션 내부 상태에 대해 사전에 정의하지 않은 질문도 던질 수 있는가" "USE WHEN: 신규 서비스/경로에 계측이 필요할 때" "PRODUCES: 이 플러그인은 역할 진입점이다 — 신호 방법론(RED/USE/Golden Signals) 선택은 observability-methodology-selector, 신호별 계측 규칙은 observability-signal-{red,use,golden}, 카디널리티 예산/탐색가능성/phase 정합성은 observability-{cardinality-budget,explorability,phase-trace}가 각각 담당한다. 이 role 자체의 produces는 그 조합 결과이며, 개별 규칙은 위 플러그인에 있다." "HAND-OFF: 장애가 실제로 발생하면 → incident-response"
